content.text:
The investigation points to one root cause, a database-call slowdown inside ts-order-service, which propagates to the user-facing services through its callers. Network, restart and CPU evidence rules out the alternatives.

```json
{
  "root_causes": [
    {
      "service": "ts-order-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "select 'norm' p, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50_ms, approx_quantile(duration,0.95)/1e6 p95_ms from normal_traces where service_name='ts-order-service' and span_name in ('SELECT Order','SELECT ts.orders','Transaction.commit') group by 2,3 union all select 'abn' p, span_name, attr_span_kind, count(*), approx_quantile(duration,0.5)/1e6, approx_quantile(duration,0.95)/1e6 from abnormal_traces where service_name='ts-order-service' and span_name in ('SELECT Order','SELECT ts.orders','Transaction.commit') group by 2,3",
          "claim": "ts-order-service's own SQL spans (SELECT Order, SELECT ts.orders, Transaction.commit) jump from about 1ms to over 1s at p50 in the incident."
        },
        {
          "kind": "metric",
          "sql": "select 'abn' p, metric, avg(value) v from abnormal_metrics where attr_k8s_pod_name like 'ts-order-service%' and metric in ('container.cpu.usage','k8s.pod.cpu.usage','k8s.container.restarts') group by 2 union all select 'norm', metric, avg(value) from normal_metrics where attr_k8s_pod_name like 'ts-order-service%' and metric in ('container.cpu.usage','k8s.pod.cpu.usage','k8s.container.restarts') group by 2",
          "claim": "ts-order-service CPU usage falls and restarts stay at zero, so the pod is not CPU-saturated or restarting."
        },
        {
          "kind": "metric",
          "sql": "select 'abn' p, metric, avg(value) v, min(value) mn, max(value) mx from abnormal_metrics where attr_k8s_pod_name like 'mysql%' and metric in ('k8s.pod.cpu.usage','k8s.pod.memory.working_set') group by 2 union all select 'norm', metric, avg(value), min(value), max(value) from normal_metrics where attr_k8s_pod_name like 'mysql%' and metric in ('k8s.pod.cpu.usage','k8s.pod.memory.working_set') group by 2",
          "claim": "mysql CPU and memory stay flat or lower during the incident, so the database server itself is not overloaded."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-order-service",
      "to": "ts-seat-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "select c.service_name caller, s.service_name callee, count(*) n, approx_quantile(s.duration,0.5)/1e6 callee_server_p50_ms from abnormal_traces s join abnormal_traces c on s.trace_id=c.trace_id and s.parent_span_id=c.span_id where s.service_name='ts-seat-service' and s.attr_span_kind='Server' group by 1,2",
          "claim": "Seat-service server spans have a child chain into order-service; seat latency rises to about 1.9s p95 as order calls stall."
        }
      ]
    },
    {
      "from": "ts-order-service",
      "to": "ts-security-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "select c.service_name caller, c.span_name, s.service_name callee, count(*) n, approx_quantile(s.duration,0.95)/1e6 callee_p95_ms from abnormal_traces c join abnormal_traces s on s.trace_id=c.trace_id and s.parent_span_id=c.span_id where c.service_name='ts-security-service' and s.service_name='ts-order-service' group by 1,2,3",
          "claim": "Security-service calls to order-service take about 11.6s at p95 during the incident."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel-service",
      "evidence": [
        {
